// sentinel: after the call every byte must be 0 or 1. Tiny or null buffers appear only for NullArgument, TooLarge, ScratchTooSmall, BadNode
// and SameTerminal failures. No test asserts any scratch value after a call. The max-size cases are sampled patterns, not exhaustive. Time
// is not measured.
